<script lang="ts">
 import{prepareNotifications,enablePush,pushSupported}from'./lib/desktop-notifications';import{isDesktopApp}from'./lib/desktop';import{onDestroy}from'svelte';import{Api}from'./lib/api';import type{Channel,NotificationPreferences,NotifyMode}from'./lib/api';import type{DeviceNotifications}from'./lib/social';
 export let api:Api;export let preferences:NotificationPreferences;export let device:DeviceNotifications;export let channel:Channel|undefined;export let onSaved:(p:NotificationPreferences)=>void;export let onDevice:(p:DeviceNotifications)=>void;
 const abort=new AbortController();let alive=true,previewAudio:HTMLAudioElement|undefined;onDestroy(()=>{alive=false;abort.abort();previewAudio?.pause();});
 let serverMode=preferences.notify,channelMode=channel?preferences.channels[channel.id]??'default':'default',allowDms=preferences.allow_dms,busy=false,error='',status='';
 let permission:NotificationPermission|'unsupported'=isDesktopApp?'granted':typeof Notification==='undefined'?'unsupported':Notification.permission;
 async function save(event:SubmitEvent){event.preventDefault();busy=true;error='';status='';try{const saved=await api.request<NotificationPreferences>('/me/preferences','PATCH',{notify:serverMode,allow_dms:allowDms,...(channel?{channels:{[channel.id]:channelMode==='default'?null:channelMode}}:{})},abort.signal);if(!alive)return;onSaved(saved);status='Preferences saved.';}catch(cause){if(alive)error=cause instanceof Error?cause.message:'Preferences could not be saved.';}finally{if(alive)busy=false;}}
 async function desktop(){if(isDesktopApp){onDevice({...device,desktop:true});status='Notifications enabled in the ChitChat app.';return;}if(typeof Notification==='undefined')return;try{permission=await Notification.requestPermission();if(permission==='granted')await prepareNotifications();onDevice({...device,desktop:permission==='granted'});if(permission==='granted')setTimeout(()=>void checkPush(),300);status=permission==='granted'?'Browser notifications enabled on this device.':'Notifications were not enabled. You can change permission in your browser settings.';}catch{error='This browser could not enable notifications.';}}
 // Push (notifications with ChitChat closed): '' = set up, else the reason; checked when the dialog opens.
 let push:string|null=null,pushBusy=false,pushResult='';
 async function checkPush(){if(isDesktopApp||!device.desktop||permission!=='granted')return;push=null;const reason=await enablePush([api]);if(alive)push=reason;}
 void checkPush();
 async function testPush(){pushBusy=true;pushResult='';try{const r=await api.request<{subscriptions:number,sent:number,failed:number,gone:number}>('/push/test','POST',undefined,abort.signal);if(!alive)return;pushResult=!r.subscriptions?'This server has no notification subscription for you yet.':r.sent?`Test sent to ${r.sent} device${r.sent===1?'':'s'}. It should appear in a few seconds${r.failed?`; ${r.failed} failed`:''}${r.gone?`; ${r.gone} expired and removed`:''}.`:`The push service did not accept the test (${r.failed} failed, ${r.gone} expired). Turn notifications off and on again here.`;}catch(cause){if(alive)pushResult=cause instanceof Error?cause.message:'The test could not be sent.';}finally{if(alive)pushBusy=false;}}
 async function testSound(){previewAudio?.pause();const audio=new Audio('/sounds/notification.mp3');previewAudio=audio;audio.volume=device.volume/100;try{await audio.play();if(alive)status='Notification sound played.';}catch{error='Sound could not play. Check your browser sound settings.';}}
</script>
<h2 id="dialog-title">Notifications &amp; messages</h2><p class="small muted">Server preferences follow your account. Browser permission, sound and volume apply to this device.</p>
<form onsubmit={save}><label>Notify me in this community<select bind:value={serverMode}><option value="all">All new messages</option><option value="mentions">Mentions only</option><option value="none">Nothing</option></select></label>{#if channel}<label>For {channel.type==='dm'?'this direct message':'#'+channel.name}<select bind:value={channelMode} disabled={channel.type==='dm'}><option value="default">Use community preference</option><option value="all">All new messages</option><option value="mentions">Mentions only</option><option value="none">Nothing</option></select></label>{/if}<p class="small muted">Direct messages notify unless this community is set to Nothing. Messages you are reading at the bottom of the visible conversation stay quiet.</p><label class="check-label"><input type="checkbox" bind:checked={allowDms}/>Allow members of this community to send me direct messages</label><button class="primary" disabled={busy}>Save preferences</button></form>
<h3>On this device</h3><p class="small muted">{#if isDesktopApp}The ChitChat app keeps running in the tray when you close its window, so it can keep notifying you until you choose Quit from the tray icon.{:else}Browser notifications include the sender and message preview. Communities on this site also send them when ChitChat is closed (push), as long as this browser is running; on iPhone and iPad, first add ChitChat to your Home Screen. Communities on other hosts notify only while ChitChat is open.{/if}</p>{#if isDesktopApp}<label>System notifications<select value={!device.desktop?'off':device.closed?'always':'open'} onchange={event=>{const mode=event.currentTarget.value;onDevice({...device,desktop:mode!=='off',closed:mode==='always'});}}><option value="always">Always, also when the window is closed to the tray</option><option value="open">Only while the window is open</option><option value="off">Off</option></select></label><p class="small muted">They show when ChitChat isn't the window you're using. Click one to open its conversation.</p>{:else if permission==='unsupported'}<p class="notice">This browser does not support desktop notifications here.</p>{:else if permission==='denied'}<p class="notice">Browser notifications are blocked. Change this site's notification permission in your browser settings to enable them.</p>{:else if device.desktop&&permission==='granted'}<button class="secondary" onclick={()=>onDevice({...device,desktop:false})}>Disable {isDesktopApp?"":"browser "}notifications</button>{:else}<button class="secondary" onclick={desktop}>Enable {isDesktopApp?"":"browser "}notifications</button>{/if}
{#if !isDesktopApp&&device.desktop&&permission==='granted'&&pushSupported()}<div class="push-status"><p class="small" role="status">{push===null?'Checking notifications while ChitChat is closed…':push===''?'✓ Set up: this device also gets notifications while ChitChat is closed.':push}</p><button class="secondary" disabled={pushBusy||push===null} onclick={testPush}>Send a test notification</button>{#if pushResult}<p class="small muted" role="status">{pushResult}</p>{/if}</div>{/if}<label class="check-label"><input type="checkbox" checked={device.sound} onchange={event=>onDevice({...device,sound:event.currentTarget.checked})}/>Play a notification sound</label><label>Notification volume: {device.volume}%<input type="range" min="0" max="100" step="1" value={device.volume} aria-label="Notification sound volume" oninput={event=>onDevice({...device,volume:Number(event.currentTarget.value)})}/></label><button class="secondary" onclick={testSound}>Test sound</button>
{#if error}<p class="error" role="alert">{error}</p>{/if}{#if status}<p class="notice" role="status">{status}</p>{/if}

<style>.push-status{display:flex;flex-direction:column;align-items:flex-start;gap:8px;margin:12px 0}</style>
